class Solution {
public:
    int maxIncreasingCells(vector<vector<int>>& mat) {
        int m = (int)mat.size(), n = (int)mat[0].size();
        vector<tuple<int,int,int>> cells;
        cells.reserve(m * n);
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                cells.emplace_back(mat[i][j], i, j);
        sort(cells.begin(), cells.end());
        vector<int> rowBest(m), colBest(n);
        int ans = 0, i = 0, N = (int)cells.size();
        while (i < N) {
            int j = i;
            while (j < N && get<0>(cells[j]) == get<0>(cells[i])) ++j;
            vector<array<int,3>> buf;
            for (int k = i; k < j; ++k) {
                auto [_, r, c] = cells[k];
                int v = 1 + max(rowBest[r], colBest[c]);
                buf.push_back({r, c, v});
                ans = max(ans, v);
            }
            for (auto [r, c, v] : buf) {
                rowBest[r] = max(rowBest[r], v);
                colBest[c] = max(colBest[c], v);
            }
            i = j;
        }
        return ans;
    }
};

