class Solution {
    public int maxIncreasingCells(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[][] cells = new int[m * n][3];
        int p = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                cells[p++] = new int[]{mat[i][j], i, j};
        Arrays.sort(cells, (a, b) -> Integer.compare(a[0], b[0]));
        int[] rowBest = new int[m], colBest = new int[n];
        int ans = 0;
        for (int i = 0, N = cells.length; i < N; ) {
            int j = i;
            while (j < N && cells[j][0] == cells[i][0]) j++;
            int[][] buf = new int[j - i][3];
            for (int k = i; k < j; k++) {
                int r = cells[k][1], c = cells[k][2];
                int v = 1 + Math.max(rowBest[r], colBest[c]);
                buf[k - i] = new int[]{r, c, v};
                ans = Math.max(ans, v);
            }
            for (int[] t : buf) {
                rowBest[t[0]] = Math.max(rowBest[t[0]], t[2]);
                colBest[t[1]] = Math.max(colBest[t[1]], t[2]);
            }
            i = j;
        }
        return ans;
    }
}

