class Solution {
public:
    int maxValue(vector<vector<int>>& events, int k) {
        sort(events.begin(), events.end());
        int n = (int)events.size();
        vector<int> nxt(n);
        for (int i = 0; i < n; ++i) {
            int lo = i + 1, hi = n, end = events[i][1];
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (events[mid][0] > end) hi = mid;
                else lo = mid + 1;
            }
            nxt[i] = lo;
        }
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
        for (int i = n - 1; i >= 0; --i) {
            for (int j = 1; j <= k; ++j) {
                dp[i][j] = max(dp[i + 1][j], events[i][2] + dp[nxt[i]][j - 1]);
            }
        }
        return dp[0][k];
    }
};

