class Solution {
public:
    int minimumTime(vector<int>& nums1, vector<int>& nums2, int x) {
        int n = (int)nums1.size();
        long long sum1 = 0, sum2 = 0;
        vector<pair<int,int>> a(n);
        for (int i = 0; i < n; ++i) {
            sum1 += nums1[i];
            sum2 += nums2[i];
            a[i] = {nums2[i], nums1[i]};
        }
        sort(a.begin(), a.end());
        vector<long long> dp(n + 1, 0);
        for (auto [b, v] : a) {
            for (int j = n; j >= 1; --j) {
                dp[j] = max(dp[j], dp[j - 1] + v + 1LL * j * b);
            }
        }
        for (int t = 0; t <= n; ++t) {
            if (sum1 + sum2 * t - dp[t] <= x) return t;
        }
        return -1;
    }
};

