class Solution {
    public int minimumTime(List<Integer> nums1, List<Integer> nums2, int x) {
        int n = nums1.size();
        long sum1 = 0, sum2 = 0;
        int[][] a = new int[n][2];
        for (int i = 0; i < n; i++) {
            sum1 += nums1.get(i);
            sum2 += nums2.get(i);
            a[i][0] = nums2.get(i);
            a[i][1] = nums1.get(i);
        }
        Arrays.sort(a, (p, q) -> Integer.compare(p[0], q[0]));
        long[] dp = new long[n + 1];
        for (int[] e : a) {
            int b = e[0], v = e[1];
            for (int j = n; j >= 1; j--) {
                dp[j] = Math.max(dp[j], dp[j - 1] + v + 1L * j * b);
            }
        }
        for (int t = 0; t <= n; t++) {
            if (sum1 + sum2 * t - dp[t] <= x) return t;
        }
        return -1;
    }
}

