class Solution:
    def minimumTime(self, nums1: list[int], nums2: list[int], x: int) -> int:
        n = len(nums1)
        pairs = sorted(zip(nums2, nums1))
        dp = [0] * (n + 1)
        for b, v in pairs:
            for j in range(n, 0, -1):
                dp[j] = max(dp[j], dp[j - 1] + v + j * b)
        sum1, sum2 = sum(nums1), sum(nums2)
        for t in range(n + 1):
            if sum1 + sum2 * t - dp[t] <= x:
                return t
        return -1

