class Solution {
    private boolean square(int x) {
        int r = (int) Math.sqrt(x);
        return r * r == x;
    }
    public int numSquarefulPerms(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);
        int[][] dp = new int[1 << n][n];
        for (int i = 0; i < n; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            dp[1 << i][i] = 1;
        }
        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == 0) continue;
                for (int j = 0; j < n; j++) {
                    if (((mask >> j) & 1) != 0) continue;
                    if (j > 0 && nums[j] == nums[j - 1] && ((mask >> (j - 1)) & 1) == 0) continue;
                    long s = (long) nums[i] + nums[j];
                    if (s <= Integer.MAX_VALUE && square((int) s))
                        dp[mask | (1 << j)][j] += dp[mask][i];
                }
            }
        }
        int ans = 0, full = (1 << n) - 1;
        for (int i = 0; i < n; i++) ans += dp[full][i];
        return ans;
    }
}

