class Solution:
    def numSquarefulPerms(self, nums: list[int]) -> int:
        nums.sort()
        n = len(nums)

        def square(x: int) -> bool:
            r = int(x ** 0.5)
            return r * r == x

        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            if i and nums[i] == nums[i - 1]:
                continue
            dp[1 << i][i] = 1
        for mask in range(1 << n):
            for i in range(n):
                if not dp[mask][i]:
                    continue
                for j in range(n):
                    if mask >> j & 1:
                        continue
                    if j and nums[j] == nums[j - 1] and not (mask >> (j - 1) & 1):
                        continue
                    if square(nums[i] + nums[j]):
                        dp[mask | (1 << j)][j] += dp[mask][i]
        full = (1 << n) - 1
        return sum(dp[full][i] for i in range(n))

