class Solution {
public:
    string shortestSuperstring(vector<string>& words) {
        int n = (int)words.size();
        vector<vector<int>> ov(n, vector<int>(n));
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) if (i != j) {
                int m = min((int)words[i].size(), (int)words[j].size());
                for (int k = m; k > 0; --k)
                    if (words[i].compare((int)words[i].size() - k, k, words[j], 0, k) == 0) {
                        ov[i][j] = k;
                        break;
                    }
            }
        const int INF = 1e9;
        vector<vector<int>> dp(1 << n, vector<int>(n, INF)), par(1 << n, vector<int>(n, -1));
        for (int i = 0; i < n; ++i) dp[1 << i][i] = (int)words[i].size();
        for (int mask = 0; mask < (1 << n); ++mask)
            for (int i = 0; i < n; ++i) {
                if (!(mask >> i & 1) || dp[mask][i] == INF) continue;
                for (int j = 0; j < n; ++j) if (!(mask >> j & 1)) {
                    int nmask = mask | (1 << j);
                    int val = dp[mask][i] + (int)words[j].size() - ov[i][j];
                    if (val < dp[nmask][j]) {
                        dp[nmask][j] = val;
                        par[nmask][j] = i;
                    }
                }
            }
        int full = (1 << n) - 1, end = 0;
        for (int i = 1; i < n; ++i) if (dp[full][i] < dp[full][end]) end = i;
        vector<int> path;
        for (int mask = full, cur = end; cur != -1; ) {
            path.push_back(cur);
            int p = par[mask][cur];
            mask ^= 1 << cur;
            cur = p;
        }
        reverse(path.begin(), path.end());
        string ans = words[path[0]];
        for (int t = 1; t < n; ++t)
            ans += words[path[t]].substr(ov[path[t - 1]][path[t]]);
        return ans;
    }
};

