class Solution {
    public String shortestSuperstring(String[] words) {
        int n = words.length;
        int[][] ov = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) if (i != j) {
                int m = Math.min(words[i].length(), words[j].length());
                for (int k = m; k > 0; k--)
                    if (words[i].endsWith(words[j].substring(0, k))) {
                        ov[i][j] = k;
                        break;
                    }
            }
        int INF = 1_000_000_000;
        int[][] dp = new int[1 << n][n];
        int[][] par = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, INF);
        for (int[] row : par) Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) dp[1 << i][i] = words[i].length();
        for (int mask = 0; mask < (1 << n); mask++)
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 0 || dp[mask][i] == INF) continue;
                for (int j = 0; j < n; j++) if (((mask >> j) & 1) == 0) {
                    int nmask = mask | (1 << j);
                    int val = dp[mask][i] + words[j].length() - ov[i][j];
                    if (val < dp[nmask][j]) {
                        dp[nmask][j] = val;
                        par[nmask][j] = i;
                    }
                }
            }
        int full = (1 << n) - 1, end = 0;
        for (int i = 1; i < n; i++) if (dp[full][i] < dp[full][end]) end = i;
        List<Integer> path = new ArrayList<>();
        for (int mask = full, cur = end; cur != -1; ) {
            path.add(cur);
            int p = par[mask][cur];
            mask ^= 1 << cur;
            cur = p;
        }
        Collections.reverse(path);
        StringBuilder sb = new StringBuilder(words[path.get(0)]);
        for (int t = 1; t < n; t++)
            sb.append(words[path.get(t)].substring(ov[path.get(t - 1)][path.get(t)]));
        return sb.toString();
    }
}

