class Solution:
    def shortestSuperstring(self, words: list[str]) -> str:
        n = len(words)
        ov = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                m = min(len(words[i]), len(words[j]))
                for k in range(m, 0, -1):
                    if words[i].endswith(words[j][:k]):
                        ov[i][j] = k
                        break
        INF = 10 ** 9
        dp = [[INF] * n for _ in range(1 << n)]
        par = [[-1] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = len(words[i])
        for mask in range(1 << n):
            for i in range(n):
                if not (mask >> i & 1) or dp[mask][i] == INF:
                    continue
                for j in range(n):
                    if mask >> j & 1:
                        continue
                    nmask = mask | (1 << j)
                    val = dp[mask][i] + len(words[j]) - ov[i][j]
                    if val < dp[nmask][j]:
                        dp[nmask][j] = val
                        par[nmask][j] = i
        full = (1 << n) - 1
        end = min(range(n), key=lambda i: dp[full][i])
        path = []
        mask, cur = full, end
        while cur != -1:
            path.append(cur)
            p = par[mask][cur]
            mask ^= 1 << cur
            cur = p
        path.reverse()
        ans = words[path[0]]
        for t in range(1, n):
            ans += words[path[t]][ov[path[t - 1]][path[t]]:]
        return ans

