class Solution {
public:
    int minNumberOfSemesters(int n, vector<vector<int>>& relations, int k) {
        vector<int> pre(n);
        for (auto& e : relations) pre[e[1] - 1] |= 1 << (e[0] - 1);
        int N = 1 << n;
        vector<int> dp(N, n + 1);
        dp[0] = 0;
        for (int mask = 0; mask < N; ++mask) {
            if (dp[mask] > n) continue;
            int can = 0;
            for (int i = 0; i < n; ++i)
                if (!(mask >> i & 1) && (pre[i] & mask) == pre[i])
                    can |= 1 << i;
            for (int sub = can; sub; sub = (sub - 1) & can) {
                if (__builtin_popcount(sub) <= k)
                    dp[mask | sub] = min(dp[mask | sub], dp[mask] + 1);
            }
        }
        return dp[N - 1];
    }
};

