class Solution:
    def minNumberOfSemesters(self, n: int, relations: list[list[int]], k: int) -> int:
        pre = [0] * n
        for a, b in relations:
            pre[b - 1] |= 1 << (a - 1)
        N = 1 << n
        dp = [n + 1] * N
        dp[0] = 0
        for mask in range(N):
            if dp[mask] > n:
                continue
            can = 0
            for i in range(n):
                if (mask >> i) & 1 == 0 and (pre[i] & mask) == pre[i]:
                    can |= 1 << i
            sub = can
            while sub:
                if sub.bit_count() <= k:
                    nxt = mask | sub
                    if dp[mask] + 1 < dp[nxt]:
                        dp[nxt] = dp[mask] + 1
                sub = (sub - 1) & can
        return dp[N - 1]

