class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = (int)seats.size(), n = (int)seats[0].size();
        vector<int> valid(m);
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (seats[i][j] == '.') valid[i] |= 1 << j;
        auto ok = [&](int mask, int rowv) {
            if (mask & ~rowv) return false;
            if (mask & (mask << 1)) return false;
            return true;
        };
        vector<int> dp(1 << n, 0), ndp(1 << n, 0);
        int ans = 0;
        for (int r = 0; r < m; ++r) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int mask = 0; mask < (1 << n); ++mask) {
                if (!ok(mask, valid[r])) continue;
                int bits = __builtin_popcount(mask);
                int best = bits;
                if (r > 0) {
                    best = 0;
                    for (int prev = 0; prev < (1 << n); ++prev) {
                        if ((mask & (prev << 1)) || (mask & (prev >> 1))) continue;
                        best = max(best, dp[prev] + bits);
                    }
                }
                ndp[mask] = best;
                ans = max(ans, best);
            }
            dp.swap(ndp);
        }
        return ans;
    }
};

