                if mask & (mask << 1):
                    continue
                bits = mask.bit_count()
                best = bits
                if r:
                    best = 0
                    for prev in range(1 << n):
                        if (mask & (prev << 1)) or (mask & (prev >> 1)):
                            continue
                        best = max(best, dp[prev] + bits)
                ndp[mask] = best
                ans = max(ans, best)
            dp = ndp
        return ans

