class Solution {
    static final int MOD = 1_000_000_007;
    private List<Integer>[] g;
    private long[] fact, invF;
    private long modPow(long a, long e) {
        long r = 1;
        for (; e > 0; e >>= 1, a = a * a % MOD) if ((e & 1) == 1) r = r * a % MOD;
        return r;
    }
    private long[] dfs(int u) {
        long ways = 1;
        int sz = 1;
        List<Integer> ch = new ArrayList<>();
        for (int v : g[u]) {
            long[] t = dfs(v);
            ways = ways * t[0] % MOD;
            ch.add((int) t[1]);
            sz += (int) t[1];
        }
        ways = ways * fact[sz - 1] % MOD;
        for (int s : ch) ways = ways * invF[s] % MOD;
        return new long[]{ways, sz};
    }
    public int waysToBuildRooms(int[] prevRoom) {
        int n = prevRoom.length;
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) g[prevRoom[i]].add(i);
        fact = new long[n + 1];
        invF = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invF[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) invF[i - 1] = invF[i] * i % MOD;
        return (int) dfs(0)[0];
    }
}

