public:
    vector<int> smallestMissingValueSubtree(vector<int>& parents, vector<int>& nums) {
        int n = (int)parents.size();
        vector<int> ans(n, 1);
        int start = -1;
        for (int i = 0; i < n; ++i) if (nums[i] == 1) start = i;
        if (start < 0) return ans;
        vector<vector<int>> g(n);
        for (int i = 1; i < n; ++i) g[parents[i]].push_back(i);
        unordered_set<int> seen;
        auto add = [&](int src) {
            stack<int> st;
            st.push(src);
            while (!st.empty()) {
                int u = st.top(); st.pop();
                if (seen.count(nums[u])) continue;
                seen.insert(nums[u]);
                for (int v : g[u]) st.push(v);
            }
        };
        int mex = 1, cur = start, prev = -1;
        while (cur != -1) {
            for (int v : g[cur]) if (v != prev) add(v);
            seen.insert(nums[cur]);
            while (seen.count(mex)) ++mex;
            ans[cur] = mex;
            prev = cur;
            cur = parents[cur];
        }
        return ans;
    }
};

