class Solution {
    public int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        int start = -1;
        for (int i = 0; i < n; i++) if (nums[i] == 1) start = i;
        if (start < 0) return ans;
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) g[parents[i]].add(i);
        Set<Integer> seen = new HashSet<>();
        int mex = 1, cur = start, prev = -1;
        while (cur != -1) {
            for (int v : g[cur]) if (v != prev) add(v, g, nums, seen);
            seen.add(nums[cur]);
            while (seen.contains(mex)) mex++;
            ans[cur] = mex;
            prev = cur;
            cur = parents[cur];
        }
        return ans;
    }
    private void add(int src, List<Integer>[] g, int[] nums, Set<Integer> seen) {
        Deque<Integer> st = new ArrayDeque<>();
        st.push(src);
        while (!st.isEmpty()) {
            int u = st.pop();
            if (!seen.add(nums[u])) continue;
            for (int v : g[u]) st.push(v);
        }
    }
}

