class Solution:
    def smallestMissingValueSubtree(self, parents: list[int], nums: list[int]) -> list[int]:
        n = len(parents)
        ans = [1] * n
        try:
            start = nums.index(1)
        except ValueError:
            return ans
        g = [[] for _ in range(n)]
        for i in range(1, n):
            g[parents[i]].append(i)
        seen: set[int] = set()

        def add(src: int) -> None:
            st = [src]
            while st:
                u = st.pop()
                if nums[u] in seen:
                    continue
                seen.add(nums[u])
                st.extend(g[u])

        mex, cur, prev = 1, start, -1
        while cur != -1:
            for v in g[cur]:
                if v != prev:
                    add(v)
            seen.add(nums[cur])
            while mex in seen:
                mex += 1
            ans[cur] = mex
            prev, cur = cur, parents[cur]
        return ans

