class Solution {
public:
    int minimumTotalPrice(int n, vector<vector<int>>& edges, vector<int>& price, vector<vector<int>>& trips) {
        vector<vector<int>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        vector<int> cnt(n);
        function<bool(int,int,int)> mark = [&](int u, int p, int t) {
            if (u == t) { cnt[u]++; return true; }
            for (int v : g[u]) if (v != p && mark(v, u, t)) {
                cnt[u]++;
                return true;
            }
            return false;
        };
        for (auto& tr : trips) mark(tr[0], -1, tr[1]);
        function<pair<int,int>(int,int)> dp = [&](int u, int p) {
            int full = cnt[u] * price[u], half = full / 2;
            for (int v : g[u]) if (v != p) {
                auto [f, h] = dp(v, u);
                full += min(f, h);
                half += f;
            }
            return pair<int,int>{full, half};
        };
        auto [f, h] = dp(0, -1);
        return min(f, h);
    }
};

