    }
    private boolean mark(int u, int p, int t) {
        if (u == t) { cnt[u]++; return true; }
        for (int v : g[u]) if (v != p && mark(v, u, t)) {
            cnt[u]++;
            return true;
        }
        return false;
    }
    private int[] dp(int u, int p) {
        int full = cnt[u] * price[u], half = full / 2;
        for (int v : g[u]) if (v != p) {
            int[] ch = dp(v, u);
            full += Math.min(ch[0], ch[1]);
            half += ch[0];
        }
        return new int[]{full, half};
