                    return True
            return False

        for s, t in trips:
            mark(s, -1, t)

        def dp(u: int, p: int):
            full = cnt[u] * price[u]
            half = full // 2
            for v in g[u]:
                if v == p:
                    continue
                f, h = dp(v, u)
                full += min(f, h)
                half += f
            return full, half

        f, h = dp(0, -1)
        return min(f, h)

