            String u = q.poll();
            if (!g.containsKey(u)) continue;
            for (String r : g.get(u)) {
                indeg.put(r, indeg.get(r) - 1);
                if (indeg.get(r) == 0) {
                    if (rec.contains(r)) ans.add(r);
                    q.add(r);
                }
            }
        }
        return ans;
    }
