    static const int MAXN = 10015;
    long long fact[MAXN], invF[MAXN];
    long long modPow(long long a, long long e) {
        long long r = 1;
        for (; e; e >>= 1, a = a * a % MOD) if (e & 1) r = r * a % MOD;
        return r;
    }
    long long C(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invF[k] % MOD * invF[n - k] % MOD;
