        for (int i = 1; i < MAXN; ++i) fact[i] = fact[i - 1] * i % MOD;
        invF[MAXN - 1] = modPow(fact[MAXN - 1], MOD - 2);
        for (int i = MAXN - 1; i > 0; --i) invF[i - 1] = invF[i] * i % MOD;
