            for (int p = 2; p * p <= k; ++p) {
                if (k % p) continue;
                int e = 0;
                while (k % p == 0) { k /= p; ++e; }
                ways = ways * C(e + n - 1, e) % MOD;
            }
            if (k > 1) ways = ways * C(n, 1) % MOD;
            ans.push_back((int)ways);
